{
  "bioavailability_prediction": "high",
  "confidence": "low",
  "revision_action": "strengthen",
  "supportive_card_ids": ["C03", "C15", "C79", "C281", "C284", "C286", "C272", "C290", "C253", "C289", "C246", "C287"],
  "contradictory_card_ids": ["C197", "C243"],
  "prediction_basis_card_ids": ["C03", "C15", "C79", "C281", "C284", "C253", "C289"],
  "claims": [
    {
      "claim": "Timolol, the closest tert-butylamino aryloxypropanolamine with measured human F, has absolute oral bioavailability of 50-75% (61.0 ± 19.2% at 0.4 mg/kg), well above the 20% threshold.",
      "card_ids": ["C03", "C15"]
    },
    {
      "claim": "L6 hepatic-clearance evidence shows timolol is metabolized mainly by CYP2D6 with minor CYP2C19 and has a rat microsomal CLint of 0.380 mL/min/mg, yet human F remains 50-75%; propranolol also has HLM CLint values of 28.8-46 µL/min/mg but normal F ~37%, so high intrinsic clearance in this class does not imply F < 20%.",
      "card_ids": ["C281", "C284", "C286", "C272", "C290", "C79"]
    },
    {
      "claim": "Polar para-substituted aryloxypropanolamines such as practolol and atenolol show low hepatic extraction/metabolic stability (atenolol in vivo intrinsic clearance 5 mL/min; microsomal CLint 1.08 mL/min/g liver), and bisoprolol has low HLM CLint (~16 µL/h/mg), supporting that the para-urea/cyclohexyl query is unlikely to undergo first-pass loss sufficient to drop F below 20%.",
      "card_ids": ["C253", "C289", "C246", "C287"]
    },
    {
      "claim": "L5 efflux evidence for urea-containing beta-blockers (pafenolol, celiprolol) is a negative absorption signal, but no F values are provided and efflux can coexist with F > 20%; it does not affirmatively establish F < 20%.",
      "card_ids": ["C197", "C243"]
    }
  ],
  "new_evidence_assessment": [
    {
      "family": "hepatic_clearance_metabolic_stability",
      "applicability": "moderate",
      "direction": "supportive",
      "decision_effect": "strengthened",
      "card_ids": ["C281", "C284", "C286", "C272", "C290", "C253", "C289", "C246", "C287"]
    }
  ],
  "evidence_gaps": [
    "No direct measured oral bioavailability exists for the query molecule; all evidence is from analogue contexts.",
    "No query-specific hepatic clearance or metabolic stability assay is available; timolol, propranolol, practolol, and atenolol are close but not identical to the query (aryl/urea differences).",
    "No direct F values are provided for pafenolol or celiprolol, so the magnitude of any efflux-related loss cannot be calibrated against the 20% threshold.",
    "Species/assay differences (rat/mouse/dog microsomes, HLM, hepatocytes) limit quantitative transfer to human F.",
    "The urea/cyclohexyl substituent may alter permeability, efflux, and metabolism relative to timolol."
  ],
  "decision_summary": "L6 hepatic-clearance/metabolic-stability evidence is supportive: the tert-butylamino aryloxypropanolamine anchor timolol has human F 50-75% despite CYP2D6-mediated metabolism, high-clearance propranolol still has normal F ~37%, and polar para-substituted analogues (practolol, atenolol) show low extraction. This strengthens the high prediction, but L5 efflux and lack of direct query F keep confidence low."
}

